<?php
declare(strict_types=1);
require_once __DIR__.'/common.php';require_once __DIR__.'/noa-bridge/storage.php';require_once __DIR__.'/noa-bridge/catalog-store.php';lab_admin();
header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');if(empty($_SESSION['noa_lab_csrf']))$_SESSION['noa_lab_csrf']=bin2hex(random_bytes(32));
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 try{lab_csrf();$b=lab_json_body();$db=noa_bridge_pdo();if(($b['action']??'')==='extract'){$p=nc_prepare($db);$_SESSION['noa_catalog_draft']=$p['digest'];lab_json(200,['digest'=>$p['digest'],'report'=>$p['report'],'peakMemoryBytes'=>memory_get_peak_usage(true)]);}if(($b['action']??'')==='apply'){$id=(string)($b['digest']??'');if(!hash_equals($_SESSION['noa_catalog_draft']??'invalid',$id))throw new DomainException('extract_in_this_session_first');$offset=$b['offset']??0;if(!is_int($offset)||$offset<0||$offset>20000)throw new InvalidArgumentException('invalid_offset');$p=nc_load_plan($id);$result=nc_apply($db,$p,(string)($b['stage']??'start'),$offset,(string)$member['mb_id']);lab_json(200,$result);}throw new InvalidArgumentException('invalid_action');
 }catch(DomainException $e){lab_json(409,['error'=>$e->getMessage()]);}catch(InvalidArgumentException $e){lab_json(400,['error'=>$e->getMessage()]);}catch(Throwable $e){error_log('[noa-catalog] '.get_class($e).' '.$e->getMessage());lab_json(503,['error'=>'catalog_operation_failed']);}
}
function nc_live_report(PDO $db,string $batch,array $report):array{
 $q=$db->prepare("SELECT entity_id,fields_json,review_fields FROM noa_catalog_versions WHERE batch_id=? AND entity_type='song'");$q->execute([$batch]);$songs=$q->fetchAll(PDO::FETCH_ASSOC);$report['songs']=count($songs);$report['incompleteSongs']=0;$pending=$db->prepare("SELECT COUNT(DISTINCT entity_id) FROM noa_catalog_conflicts WHERE batch_id=? AND status<>'resolved'");$pending->execute([$batch]);$report['reviewSongs']=(int)$pending->fetchColumn();
 foreach($songs as $r){$f=json_decode($r['fields_json'],true);if(empty($f['title'])||empty($f['lyricsBlock'])||empty($f['sunoUrl'])&&empty($f['sunoShareUrl'])||empty($f['youtubeUrl']))$report['incompleteSongs']++;}
 $q=$db->prepare("SELECT p.playlist_id,v.fields_json,a.genre_id,a.act_number,COUNT(t.position) AS tracks,COUNT(DISTINCT t.variant_id) AS variants,SUM(t.song_id IS NULL) AS unresolved,SUM(t.status<>'verified') AS pending FROM noa_catalog_playlists p JOIN noa_catalog_versions v ON v.entity_id=p.playlist_id AND v.batch_id=? LEFT JOIN noa_catalog_acts a ON a.act_id=p.act_id LEFT JOIN noa_catalog_tracks t ON t.playlist_id=p.playlist_id AND t.batch_id=v.batch_id GROUP BY p.playlist_id,v.fields_json,a.genre_id,a.act_number ORDER BY a.genre_id,a.act_number,p.playlist_id");$q->execute([$batch]);$report['lists']=[];$report['acts']=0;
 foreach($q as $r){$f=json_decode($r['fields_json'],true);$act=(int)($r['act_number']??0);if($act)$report['acts']++;$report['lists'][]=['id'=>$r['playlist_id'],'genre'=>$r['genre_id']??($f['source']??'user-library'),'act'=>$act,'title'=>$f['title']??'목록','tracks'=>(int)$r['tracks'],'variants'=>(int)$r['variants'],'unresolved'=>(int)$r['unresolved'],'orderVerified'=>(int)$r['variants']===1&&(int)$r['unresolved']===0&&(int)$r['pending']===0];}
 $report['playlists']=count($report['lists']);return $report;
}
function nce(string $s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$report=null;$applied=null;$conflicts=[];$draft=$_SESSION['noa_catalog_draft']??null;
try{$db=noa_bridge_pdo();if(nc_exists($db,'noa_catalog_batches')){$applied=$db->query("SELECT batch_id,report,applied_at FROM noa_catalog_batches WHERE status='applied' ORDER BY applied_at DESC,batch_id DESC LIMIT 1")->fetch(PDO::FETCH_ASSOC);if($applied){$report=json_decode($applied['report'],true);$q=$db->prepare("SELECT conflict_id,entity_id,field_name,alternatives,status FROM noa_catalog_conflicts WHERE batch_id=? AND status<>'resolved' ORDER BY entity_id,field_name");$q->execute([$applied['batch_id']]);$conflicts=$q->fetchAll(PDO::FETCH_ASSOC);}}if(isset($_GET['draft'])&&$draft&&is_file(nc_plan_path($draft)))$report=nc_load_plan($draft)['report'];}catch(Throwable $e){error_log('[noa-catalog-view] '.get_class($e));}
if($applied&&!isset($_GET['draft'])){try{$report=nc_live_report($db,$applied['batch_id'],$report??[]);}catch(Throwable $e){error_log('[noa-catalog-stats] '.get_class($e));}}
?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>음악 SQL 통합 | NOA STUDIO</title><link rel="stylesheet" href="/noa-ui.css?v=20261021-home1"><link rel="stylesheet" href="/noa-ai-lab.css"><script src="/noa-brand.js?v=20261021-brand1" defer></script><script src="/noa-ui.js?v=20261021-world2" defer></script><style>.catalog-table{width:100%;border-collapse:collapse;text-align:left;font-size:14px}.catalog-table td,.catalog-table th{padding:12px;border-bottom:1px solid var(--noa-line)}.catalog-scroll{overflow:auto}.catalog-number{font-size:28px;color:var(--noa-accent)}.catalog-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:20px}.catalog-stats span{display:block;color:var(--noa-muted)}.catalog-toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.catalog-icon{border-radius:50%!important;width:48px;height:48px;font-size:23px}.catalog-review pre{max-height:250px;overflow:auto}</style></head><body class="noa-page"><main><p class="noa-eyebrow">NOA STUDIO / MUSIC DATA</p><h1>원본 가져오기·통합 등록</h1><p><a href="/noa-quality.php">곡정보 검사·정리 열기 →</a> · 기존 곡 오류와 중복 값은 이곳에서 조치하세요. 아래 기능은 이전 원본을 추가로 가져올 때 사용합니다.</p><p class="noa-muted">곡·ACT·플레이리스트와 수록 순서를 분리하고, 원본과 필드별 근거를 함께 보관합니다. 기존 회원·음악·설정 테이블은 수정하지 않습니다.</p><div class="catalog-toolbar"><button id="extract" class="catalog-icon" aria-label="원본 추출·병합 검증" title="원본 추출·병합 검증">⟳</button><span>원본 추출·검증</span><button id="apply" class="catalog-icon" aria-label="검증한 데이터 SQL 등록" title="검증한 데이터 SQL 등록" disabled>⇥</button><span>검증 결과 SQL 등록</span><a href="/noa-catalog.php">통합 음악·플레이리스트 보기 ↗</a><a href="/noa-ai-lab.php">AI LAB</a></div><p id="catalog-status" role="status"><?=$applied?'SQL 등록 완료 · '.nce($applied['applied_at']):'먼저 원본 추출·병합 검증을 실행하세요.'?></p><section class="lab-panel"><h2>원본 수집 결과</h2><div id="catalog-stats" class="catalog-stats"></div><p id="catalog-evidence" class="noa-muted"></p><p class="noa-muted">정보 부족 = 제목·가사·Suno·YouTube 중 하나 이상이 없거나 충돌로 확정되지 않은 곡입니다. 정보가 부족해도 식별된 곡은 등록합니다. 병합 수는 동일 곡을 가리키는 반복 원본 기록 수입니다.</p><details><summary>수집 범위와 확인하지 못한 저장본</summary><ul id="catalog-limits"></ul></details></section><section class="lab-panel"><h2>ACT·플레이리스트 수록곡 검증</h2><div class="catalog-scroll"><table class="catalog-table"><thead><tr><th>장르 / 목록</th><th>ACT</th><th>수록곡</th><th>미식별</th><th>순서</th></tr></thead><tbody id="catalog-lists"></tbody></table></div></section><section class="lab-panel"><h2>아직 확정하지 않은 원본 충돌</h2><p><a href="/noa-quality.php">값을 비교하고 확정하기 →</a></p><p class="noa-muted">서로 다른 비어 있지 않은 값은 자동 선택하지 않습니다. 각 원본과 대안을 보존했습니다. 확정되지 않은 필드는 통합 화면에서 검토 중으로 표시됩니다.</p><p>현재 등록본의 충돌 필드 <?=count($conflicts)?>건</p><?php foreach($conflicts as $c):?><details class="catalog-review"><summary><?=nce(substr($c['entity_id'],0,12).' · '.$c['field_name'].' · '.$c['status'])?></summary><?php foreach(json_decode($c['alternatives'],true) as $v):?><pre><?=nce(nc_json($v['value']??$v))?></pre><?php endforeach;?></details><?php endforeach;?></section></main>
<script>
(()=>{'use strict';const csrf=<?=json_encode($_SESSION['noa_lab_csrf'])?>;let digest=<?=json_encode($draft)?>;const $=id=>document.getElementById(id);function el(tag,text){const e=document.createElement(tag);e.textContent=text;return e;}function show(report){if(!report)return;$('catalog-stats').replaceChildren(...[['songs','식별된 통합 곡'],['duplicateSongOccurrencesMerged','반복 원본 기록 병합'],['incompleteSongs','정보 부족 곡'],['reviewSongs','충돌 검토 곡'],['acts','ACT'],['playlists','플레이리스트']].map(([key,label])=>{const d=el('div',''),n=el('strong',Number(report[key]).toLocaleString());n.className='catalog-number';d.append(n,el('span',label));return d;}));$('catalog-evidence').textContent=`추출 원본 기록 ${report.sourceOccurrences.toLocaleString()}건 · 고유 원본 바이트 ${report.uniqueSourceBytes.toLocaleString()}종 · 식별 실패 ${report.unidentifiedSources.length}건`;$('catalog-limits').replaceChildren(...report.limits.map(x=>el('li',x)));$('catalog-lists').replaceChildren(...report.lists.map(l=>{const tr=el('tr','');for(const value of [l.genre+' · '+(l.title||'제목 검토 중'),l.act||'—',l.tracks,l.unresolved,l.orderVerified?'검증됨':'검토 필요'])tr.append(el('td',String(value)));return tr;}));}async function post(body){const r=await fetch('/noa-catalog-admin.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-NOA-CSRF':csrf},body:JSON.stringify(body)});let data;try{data=await r.json();}catch{throw Error('서버 응답을 읽지 못했습니다.');}if(!r.ok)throw Error(data.error||'통합 작업을 완료하지 못했습니다.');return data;}
$('extract').onclick=async()=>{$('extract').disabled=true;$('apply').disabled=true;$('catalog-status').textContent='원본·현재 DB·필드 충돌과 수록 순서를 검증하고 있습니다.';try{const result=await post({action:'extract'});digest=result.digest;show(result.report);$('apply').disabled=false;$('catalog-status').textContent='추출·병합 검증 완료. 원본과 충돌을 보존하여 SQL에 등록할 수 있습니다.';}catch(e){$('catalog-status').textContent=e.message;}finally{$('extract').disabled=false;}};
$('apply').onclick=async()=>{$('extract').disabled=true;$('apply').disabled=true;try{let next={stage:'start',offset:0};for(let turn=0;turn<200;turn++){$('catalog-status').textContent='SQL 통합 진행 · '+next.stage+' · '+next.offset;const result=await post({action:'apply',digest,...next});if(result.done){$('catalog-status').textContent=result.replayed?'동일 통합본이 이미 등록되어 있습니다. 중복 등록하지 않았습니다.':'SQL 등록·원본 체크섬·곡 수·수록 순서 검증 완료.';if(result.report)show(result.report);return;}next=result;}throw Error('작업 요청 상한에 도달했습니다. 같은 통합본으로 재개하세요.');}catch(e){$('catalog-status').textContent=e.message;}finally{$('extract').disabled=false;$('apply').disabled=false;}};show(<?=json_encode($report,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>);})();
</script></body></html>
